"""Make the share graphic from the site's actual botanical assets and glass shader."""
from pathlib import Path
import re,json,sys,io
import qrcode
import qrcode.image.svg
root=Path(__file__).resolve().parents[2]
source=(root/'public/index.html').read_text()
assets=json.loads(re.search(r'const BOTANICAL_ART=([\s\S]*?);\n',source)[1])
url='https://guizhou-trip.tc6vrhdy6t.workers.dev/'
qr=qrcode.QRCode(version=None,error_correction=qrcode.constants.ERROR_CORRECT_M,box_size=8,border=4)
qr.add_data(url);qr.make(fit=True)
image=qr.make_image(image_factory=qrcode.image.svg.SvgPathImage);buffer=io.BytesIO();image.save(buffer)
qr_svg=buffer.getvalue().decode().replace('<?xml version=\'1.0\' encoding=\'UTF-8\'?>','')
css="""
*{box-sizing:border-box}body{margin:0;background:#DAECF4;color:#232826;font-family:-apple-system,"PingFang SC","Microsoft YaHei",sans-serif;-webkit-font-smoothing:antialiased}h1,h2,h3,p{margin:0}#poster{width:1080px;height:1900px;overflow:hidden;position:relative;background:#DAECF4}header{height:390px;position:relative;isolation:isolate;background:#DAECF4 var(--botanical-cover) center top/1080px auto no-repeat;padding:54px 76px 0}header:before{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,transparent 10%,#DAECF4DF 32%,#DAECF4DF 69%,transparent 92%)}.brand-row{display:flex;align-items:center;justify-content:space-between;font-size:18px;letter-spacing:.12em;color:#232826c9}.brand-row>span:first-child{padding:8px 13px;background:#DAECF4B3;border-radius:25px;backdrop-filter:blur(4px)}.edition{border:1px solid #509EAB65;border-radius:28px;padding:8px 17px;letter-spacing:.03em;background:#DAECF42e;backdrop-filter:blur(5px)}h1{font-size:76px;line-height:1.4;font-weight:550;letter-spacing:.07em;margin-top:31px;text-align:center}header .sub{font-size:27px;letter-spacing:.06em;margin-top:8px;text-align:center}header .dates{font-size:19px;letter-spacing:.10em;margin-top:19px;color:#232826bf;text-align:center}main{position:relative;isolation:isolate;padding:0 60px}main:before{content:"";position:absolute;inset:48px 0 0;background:var(--botanical-main) center top/1080px auto repeat-y;opacity:.36;z-index:-2}.glass-optics{position:absolute;inset:0;pointer-events:none;width:100%;height:100%;z-index:-1}.trip-cover>.glass-optics{z-index:0}header>*{position:relative;z-index:1}.card{position:relative;isolation:isolate;border:1px solid #509EAB50;border-radius:28px;background:#DAECF428;box-shadow:inset 0 1px 1px #DAECF4CC,inset 0 -1px 1px #23282613,0 7px 25px #2328260B;backdrop-filter:blur(5px) saturate(115%);padding:30px 34px}.gl-optics-ready .card{backdrop-filter:none;background:#DAECF430}.card:after{content:"";position:absolute;inset:1px;border-radius:26px;pointer-events:none;border-top:1px solid #DAECF47D}.section-label{display:flex;align-items:center;gap:11px;font-size:18px;color:#232826ba;letter-spacing:.05em;margin-bottom:13px}.number{display:flex;align-items:center;justify-content:center;width:31px;height:31px;border:1px solid #509EAB66;border-radius:50%;font-size:14px;letter-spacing:0}.tag{margin-left:auto;background:#509EAB20;border:1px solid #509EAB40;padding:3px 11px;font-size:14px;border-radius:20px;color:#232826}h2{font-size:39px;letter-spacing:.035em;font-weight:550;line-height:1.5}h3{font-size:31px;font-weight:550;letter-spacing:.03em;line-height:1.55}.food{height:283px;padding:28px 34px}.food h2{font-size:39px}.food .pills{display:flex;gap:9px;margin-top:14px}.pill{border:1px solid #509EAB50;padding:5px 14px;border-radius:22px;font-size:17px;background:#DAECF414}.body{font-size:23px;line-height:1.85;margin-top:13px;color:#232826D6;letter-spacing:.012em}.food .body{margin-top:15px;font-size:22px}.two{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:20px}.two .card{height:309px}.two h3{font-size:32px}.mini-list{display:flex;gap:8px;flex-wrap:wrap;margin-top:19px}.mini-list span{display:flex;align-items:center;gap:8px;border:1px solid #509EAB42;border-radius:13px;padding:7px 10px;font-size:17px}.mini-list i{display:inline-block;width:15px;height:15px;border-radius:4px;border:1px solid #509EAB}.mini-list i.checked{background:#509EAB;position:relative}.mini-list i.checked:before{content:"";position:absolute;width:7px;height:4px;border-left:1px solid #DAECF4;border-bottom:1px solid #DAECF4;transform:rotate(-45deg);top:3px;left:3px}.weather-row{display:flex;gap:13px;margin-top:18px;align-items:baseline}.weather-row strong{font-size:34px;font-weight:500;font-variant-numeric:tabular-nums;letter-spacing:-.04em}.weather-row span{font-size:16px}.two .body{font-size:21px;line-height:1.8}.route{margin-top:20px;height:291px}.route .section-label{margin-bottom:9px}.route-list{display:grid;grid-template-columns:150px 1fr;gap:10px 15px;margin-top:14px;font-size:22px;line-height:1.7}.route-date{font-size:18px;display:flex;gap:8px;align-items:center;color:#232826ba}.route-date i{width:7px;height:7px;background:#558F14;border-radius:50%;display:block}.route strong{font-weight:550}.route .foot{font-size:18px;color:#232826b5;margin-top:14px}.polish{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:20px}.polish .card{height:191px;padding:25px 28px}.polish .section-label{font-size:16px;margin-bottom:10px}.polish h3{font-size:27px}.polish .body{font-size:19px;margin-top:8px;line-height:1.8}.share{display:flex;align-items:center;gap:29px;margin-top:30px;padding:0 12px;height:225px}.qr{flex-shrink:0;width:190px;height:190px;background:#fff;border:1px solid #509EAB66;border-radius:18px;overflow:hidden;box-shadow:0 5px 15px #2328260A}.qr svg{display:block;width:100%;height:100%}.share h3{font-size:32px;letter-spacing:.04em}.share p{font-size:20px;margin-top:11px;color:#232826C7;line-height:1.85}.share small{font-size:15px;color:#232826A5;display:block;margin-top:14px;letter-spacing:.04em}footer{font-size:16px;text-align:center;color:#232826A6;letter-spacing:.06em;margin-top:19px}
"""
head=assets['original']['light']
css=':root{--bg:#DAECF4;--botanical-cover:url("'+head['cover']+'");--botanical-main:url("'+head['main']+'")}'+css
# Preserve the same sampler, rounded edge and matching tile position as the website.
optics=(root/'ui/liquid-glass/optics.js').read_text()
optics=optics.replace("'.card:not(.food-live-atlas),.alert,.event-card,.stay-intro,.food-detail-copy,.map-fold,.route-panel,.daily-kit,.overview-day,.overview-stay,.city-buttons button,.reset-button,.address-copy,.external-button,.day-footer button,.food-filters button'","'.card'")
html="""<!doctype html><html lang="zh-CN" data-look="original" data-palette="light"><meta charset="utf-8"><title>贵州同行 · 更新介绍</title><style>"""+css+"""</style><body><div id="poster"><header class="trip-cover"><div class="brand-row"><span>同行 · 贵州</span><span class="edition">11.19 更新</span></div><h1>山水间，同行</h1><p class="sub">旅行小站更新了，出发前来看看。</p><p class="dates">11.27—11.30 · 4 天 3 晚</p></header><main id="main-content">
<section class="card food"><div class="section-label"><span class="number">01</span>美食地图<span class="tag">新增</span></div><h2>在地图上，找到想吃的</h2><div class="pills"><span class="pill">贵阳市区</span><span class="pill">安顺</span><span class="pill">民宿周边</span></div><p class="body">看位置、挑店铺，比较两家店的距离。<br>选好后，直接打开导航或大众点评。</p></section>
<div class="two"><section class="card"><div class="section-label"><span class="number">02</span>每日随身清单<span class="tag">新增</span></div><h3>今天该带什么？</h3><p class="body">每天行程前看一眼，<br>出门前逐项勾好。</p><div class="mini-list"><span><i class="checked"></i>身份证</span><span><i></i>登山鞋</span><span><i></i>雨衣</span></div></section><section class="card"><div class="section-label"><span class="number">03</span>旅行天气<span class="tag">更新</span></div><h3>跟着行程看天气</h3><p class="body">贵阳、安顺分开看，<br>四天预报已补齐。</p><div class="weather-row"><strong>6—19°C</strong><span>早晚注意添衣</span></div></section></div>
<section class="card route"><div class="section-label"><span class="number">04</span>行程安排<span class="tag">调整</span></div><h3>安顺玩一天，周日慢慢逛</h3><div class="route-list"><span class="route-date"><i></i>11/28 周六</span><strong>黄果树 → 铜鼓荡 · 大巴往返</strong><span class="route-date"><i></i>11/29 周日</span><strong>市区午餐 → 黔灵山 · 睡个懒觉再出发</strong></div><p class="foot">每天用餐处都能直接跳转对应区域的美食。</p></section>
<div class="polish"><section class="card"><div class="section-label"><span class="number">05</span>总览</div><h3>路线在前，信息更简洁</h3><p class="body">打开先看路线，再按日期看当天。</p></section><section class="card"><div class="section-label"><span class="number">06</span>界面</div><h3>熟悉的蓝绿，更通透</h3><p class="body">玻璃卡片 · 日夜配色 · 轻柔切换</p></section></div>
<div class="share"><div class="qr">"""+qr_svg+"""</div><div><h3>长按识别，打开旅行小站</h3><p>路线、吃什么、带什么，都放在这里。<br>吃饭可以分头行动，回院子再分享。</p><small>天气为 11/19 趋势预报，出发前再看最新情况。</small></div></div>
<footer>山间 · 城市 · 一路同行</footer>
</main></div><script>const BOTANICAL_ART="""+json.dumps(assets,separators=(',',':'))+";\n"+optics+"</script></body></html>"
target=Path(sys.argv[1]) if len(sys.argv)>1 else root/'public/preview/update-poster.html'
target.parent.mkdir(parents=True,exist_ok=True);target.write_text(html);print(target)
